def _process_and_respond(self, user_text: str):
    """Full pipeline: user text -> Claude -> TTS -> listen for follow-up -> repeat."""
    try:
        self._respond_once(user_text)

        followup_timeout = self._config.get("conversation", {}).get("followup_timeout", 8.0)
        max_turns = self._config.get("conversation", {}).get("max_followup_turns", 20)

        for turn in range(max_turns):
            if not self._listener or self._stop_event.is_set():
                break

            log.info("Awaiting follow-up...")
            if self._indicator:
                self._indicator.set_state("listening")

            followup = self._listener.capture_followup(timeout=followup_timeout)

            if not followup:
                log.info("No follow-up - ending conversation")
                break

            log.info(f"Follow-up (turn {turn + 2}): {followup}")
            self._respond_once(followup)

    except Exception as e:
        log.error(f"Response pipeline error: {e}")
        if self._indicator:
            self._indicator.notify(f"Error: {str(e)[:40]}", 4000)
    finally:
        self._return_to_idle()

def _respond_once(self, user_text: str):
    """Single turn: user text -> Claude (with tools) -> TTS."""
    self._memory.add_user(user_text)
    messages = self._memory.get_messages()
    system = self._memory.system_prompt

    if self._indicator:
        self._indicator.set_state("thinking")

    tools = self._tools.get_anthropic_tools()

    if tools:
        full_response = self._llm.chat_with_tools(
            messages=messages,
            tools=tools,
            tool_executor=self._tools.execute_tool_call,
            system=system,
        )
        if full_response:
            if self._indicator:
                self._indicator.set_state("speaking")
            self._tts.speak_streamed(
                iter([full_response]),
                on_amplitude=self._on_amplitude,
            )
            self._memory.add_assistant(full_response)
    else:
        text_gen, collector = self._llm.chat_stream_collect(messages, system=system)
        if self._indicator:
            self._indicator.set_state("speaking")
        self._tts.speak_streamed(
            text_gen,
            on_amplitude=self._on_amplitude,
        )
        full_response = "".join(collector)
        if full_response:
            self._memory.add_assistant(full_response)
